/**
 * Independent golden schema and fingerprint snapshot for the seven stores using
 * src/shared/schema-ledger.ts. These values represent the schema existing databases
 * must contain, rather than expectations generated by the shared implementation under
 * test.
 *
 * Preserve the SQL and fingerprints when validating the normalizer. A mismatch requires
 * investigating schema compatibility; regenerating the expected values would hide that
 * incompatibility.
 */

/** Persisted schema object paired with its independent expected fingerprint. */
export interface GoldenSchemaObject {
  /** `"<type>:<name>"`, keyed exactly as a `sqlite_master` sweep row is keyed. */
  readonly key: string;
  /**
   * Persisted sqlite_master.sql text, byte for byte. SQLite strips IF NOT EXISTS when
   * storing tables, indexes, triggers and views. To detect that clause in definitions,
   * inspect the source schemaDefinitions rather than this persisted DDL.
   */
  readonly ddl: string;
  /** Expected normalized form of the persisted DDL. */
  readonly fingerprint: string;
}

export interface GoldenStoreSchema {
  readonly ledgerTable: string;
  /** The single schema version a freshly created database records. */
  readonly version: number;
  /** Objects inside the store's own `sqlite_master` sweep -- exactly the set its fingerprint invariant requires. */
  readonly swept: readonly GoldenSchemaObject[];
  /**
   * Objects the store creates (or SQLite creates for it) that its own sweep
   * does NOT cover, pinned so they cannot quietly disappear.
   *
   * `sqlite_sequence` is SQLite's own, created by `AUTOINCREMENT`.
   */
  readonly outsideSweep: readonly GoldenSchemaObject[];
}

